Q: How do I track keyboard changes in xcb-xkb when layout is toggled? A: <p>Well xcb is definitely a tough one, not to mention that on my Debian your example did not work, and when I've used <code>setxkbmap</code> it disabled permanently ALT+SHIFT for the testing. Anyway I was able to hit the InidcatorState change, maybe you need to handle the state in the handle events. I've added few printf calls just to see what event I am getting and also refer to this file: <a href="https://xcb.freedesktop.org/manual/xkb_8h_source.html" rel="nofollow noreferrer">https://xcb.freedesktop.org/manual/xkb_8h_source.html</a> not well documented api in any case. Here is the small change I had to do to make it work, so maybe it will help you find a way to capture the next event.</p>
<pre><code>// Source - https://stackoverflow.com/q/79924054
// Posted by cutecoder, modified by community. See post 'Timeline' for change history
// Retrieved 2026-04-11, License - CC BY-SA 4.0

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

#include &lt;xcb/xcb.h&gt;
#include &lt;xcb/xkb.h&gt;

struct display {
    xcb_connection_t *xcb;
    uint8_t xkb_base_event, xkb_base_error;
    int32_t keyboard_device_id;
} display;

void open_display(void)
{
    int connection_error;
    xcb_xkb_use_extension_cookie_t xkb_cookie;
    xcb_xkb_get_device_info_cookie_t device_cookie;
    const xcb_query_extension_reply_t *extension_reply;
    xcb_xkb_use_extension_reply_t *xkb_reply;
    xcb_xkb_get_device_info_reply_t *device_reply;
    xcb_generic_error_t *error;

    display.xcb = xcb_connect(NULL, NULL);
    if (!display.xcb) {
      printf(&quot;oops\r\n&quot;);
      exit(-1);
    } else {
      printf(&quot;ook\r\n&quot;);
    }

    xcb_prefetch_extension_data(display.xcb, &amp;xcb_xkb_id);

    xkb_cookie = xcb_xkb_use_extension(display.xcb,
            XCB_XKB_MAJOR_VERSION, XCB_XKB_MINOR_VERSION);

    device_cookie = xcb_xkb_get_device_info(display.xcb,
            XCB_XKB_ID_USE_CORE_KBD, 0, 0, 0, 0, 0, 0);

    extension_reply = xcb_get_extension_data(display.xcb, &amp;xcb_xkb_id);

    display.xkb_base_event = extension_reply-&gt;first_event;
    display.xkb_base_error = extension_reply-&gt;first_error;

    xkb_reply = xcb_xkb_use_extension_reply(display.xcb, xkb_cookie, &amp;error);
    free(xkb_reply);

    device_reply = xcb_xkb_get_device_info_reply(display.xcb, device_cookie,
            NULL);
    display.keyboard_device_id = device_reply-&gt;deviceID;
    free(device_reply);

    xcb_xkb_select_events(display.xcb, display.keyboard_device_id, ~0, 0, ~0, 0, 0, NULL);
}

static void handle_xkb_event(xcb_generic_event_t *generic_event)
{

    switch ((( xcb_xkb_new_keyboard_notify_event_t*)generic_event)-&gt;xkbType) {

    case XCB_XKB_NEW_KEYBOARD_NOTIFY: {
        xcb_xkb_new_keyboard_notify_event_t *event;
    printf(&quot;xkb: NEW_KEYBOARD_NOTIFY\n&quot;);
        event = (xcb_xkb_new_keyboard_notify_event_t*) generic_event;
        if (event-&gt;oldDeviceID == display.keyboard_device_id) {
            printf(&quot;xkb: NEW_KEYBOARD_NOTIFY\n&quot;);
            display.keyboard_device_id = event-&gt;deviceID;
        }
        break;
    }

    case XCB_XKB_MAP_NOTIFY: {
        xcb_xkb_map_notify_event_t *event;

        event = (xcb_xkb_map_notify_event_t*) generic_event;
        printf(&quot;xkb: MAP_NOTIFY\n&quot;);
        break;
    }

    case XCB_XKB_STATE_NOTIFY: {
        xcb_xkb_state_notify_event_t *event;

        event = (xcb_xkb_state_notify_event_t*) generic_event;
        printf(&quot;xkb: STATE_NOTIFY\n&quot;);
        break;
    }

    case XCB_XKB_INDICATOR_STATE_NOTIFY: {

        xcb_xkb_indicator_state_notify_event_t *event;
        event = (xcb_xkb_indicator_state_notify_event_t*) generic_event;
    if (event-&gt;xkbType == XCB_XKB_NEW_KEYBOARD_NOTIFY) {
      xcb_xkb_new_keyboard_notify_event_t *event;
      printf(&quot;xkb: NEW_KEYBOARD_NOTIFY\n&quot;);
      event = (xcb_xkb_new_keyboard_notify_event_t*) generic_event;
      if (event-&gt;oldDeviceID == display.keyboard_device_id) {
            printf(&quot;xkb: NEW_KEYBOARD_NOTIFY\n&quot;);
            display.keyboard_device_id = event-&gt;deviceID;
      }
    } else {
      printf(&quot;evnet is: %d\r\n&quot;, event-&gt;xkbType);
    }
        printf(&quot;xkb: INDICATOR_STATE_NOTIFY\n&quot;);
        break;
    }

    case XCB_XKB_EXTENSION_DEVICE_NOTIFY: {
         xcb_xkb_extension_device_notify_event_t  *event;
        event = ( xcb_xkb_extension_device_notify_event_t *) generic_event;
    if (event-&gt;xkbType == XCB_XKB_NEW_KEYBOARD_NOTIFY) {
      xcb_xkb_new_keyboard_notify_event_t *event;
      printf(&quot;xkb: NEW_KEYBOARD_NOTIFY\n&quot;);
      event = (xcb_xkb_new_keyboard_notify_event_t*) generic_event;
      if (event-&gt;oldDeviceID == display.keyboard_device_id) {
            printf(&quot;xkb: NEW_KEYBOARD_NOTIFY\n&quot;);
            display.keyboard_device_id = event-&gt;deviceID;
      }
    }
        printf(&quot;xkb: EXTENSION_DEVICE_NOTIFY\n&quot;);
        break;
    }
    }
}

int main(void)
{
    xcb_generic_event_t *event;

    open_display();

    for (;;) {
      xcb_flush(display.xcb);
      while (event = xcb_wait_for_event(display.xcb), event != NULL) {
        if (event-&gt;response_type == display.xkb_base_event) {
      handle_xkb_event(event);
        } else {
      printf(&quot;shall not pass here\r\n&quot;);
    }

        free(event);
      }
