Q: How do I detect a button press in a normal Java file? A: <p>This looks like some missing code in the java <strong>JButton</strong> implementation.</p>
<p>Here's my code, as of 4/22/2025.  It's inside the usual <strong>JFrame</strong> code, Windows 11.</p>
<p>The <strong>actionPerformed</strong> code is only run when the button is <strong>released</strong>, not <strong>pressed</strong>.</p>
<p>This is a button that is restored upon release.  It works, but the <strong>addActionListener</strong> needs something to <em>catch</em> a press, not just a <em>release</em>.  <strong>What might that be?</strong></p>
<pre><code>        JButton flash = new JButton(&quot;Flash&quot;);
        // Set the button's location relative to a simple Frame
        flash.setBounds(40, 50, 100, 20);   // x, y, w, h
        flash.setActionCommand(&quot;flash&quot;); // chooses a link in actionPerformed
        flash.setMnemonic('F');  // press ALT F as key stroke
        flash.setEnabled(true);
        flash.setBackground(buttonOffColor);
        flash.setForeground(buttonOnColor);
            flash.addActionListener(
            new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                System.out.println(&quot;Button flash released&quot;);
            }
        });
</code></pre>

Q: Improving insert query for SCD2 solution A: <pre><code>from __future__ import annotations

import json
import re
import shutil
import pandas as pd
import logging
from datetime import datetime
from pathlib import Path
from typing import List, Optional, Dict, Any, TYPE_CHECKING

if TYPE_CHECKING:
    from modules.dq import (
        DataContract,
        DataObjectFactory,
        DQRunner,
        DQRunnerResult,
        DataObjectError,
        DataObjectResolvingError,
        DataContractError,
        DataContractLoadError,
        DataContractNotFoundError,
    )

from models.processing_result import ProcessingResult
from utils.config_loader import ConfigLoader
from trackers import ExecutionTracker, MockExecutionTracker


class DQProcessor:
    &quot;&quot;&quot;Processeur Data Quality pour les fichiers extraits de PGP.&quot;&quot;&quot;

    def __init__(self, config_loader: Optional[ConfigLoader] = None, tracker: Optional[ExecutionTracker] = None):

        self.config_loader = config_loader or ConfigLoader()
        self.tracker = tracker or MockExecutionTracker()
        self.logger = logging.getLogger(__name__)
        # `DQRunner` est instancié en lazy à l'intérieur de _process_single_csv_file
        # pour que DQProcessor() n'échoue pas si la lib `dataquality` n'est pas
        # encore installée. Voir le module docstring.

    def process_extracted_files(self) -&gt; ProcessingResult:

        try:
            # Charger la configuration
            settings = self.config_loader.config
            pgp_config = settings.get('pgp', {})
            dq_config = settings.get('data_quality', {})

            extracted_dir = pgp_config.get('extracted_dir', '/data/extracted')
            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            self.logger.info(f&quot;Starting DQ processing from {extracted_dir}&quot;)

            # Découvrir les fichiers CSV extraits
            csv_files = self._discover_csv_files(extracted_dir)

            if not csv_files:
                return ProcessingResult(
                    success=True,
                    message=&quot;Aucun fichier CSV à traiter&quot;,
                    metadata={'extracted_dir': extracted_dir}
                )

            # Traiter chaque fichier CSV
            results = []
            for csv_file in csv_files:
                result = self._process_single_csv_file(
                    csv_file_path=csv_file,
                    dq_out_dir=dq_out_dir,
                    dq_reports_dir=dq_reports_dir
                )
                results.append(result)

                # Log du résultat intermédiaire
                if result.success:
                    self.logger.info(f&quot;✓ {Path(csv_file).name}: DQ processing completed&quot;)
                else:
                    self.logger.error(f&quot;✗ {Path(csv_file).name}: {result.error}&quot;)

            # Analyser les résultats globaux
            successful = [r for r in results if r.success]
            failed = [r for r in results if not r.success]

            if failed:
                return ProcessingResult(
                    success=False,
                    message=f&quot;Traitement DQ partiel: {len(successful)}/{len(results)} fichiers traités&quot;,
                    error=f&quot;{len(failed)} fichiers ont échoué&quot;,
                    metadata={
                        'extracted_dir': extracted_dir,
                        'dq_out_dir': dq_out_dir,
                        'total_files': len(csv_files),
                        'successful_files': len(successful),
                        'failed_files': len(failed),
                        'results': results
                    }
                )

            return ProcessingResult(
                success=True,
                message=f&quot;Traitement DQ réussi: {len(successful)} fichier(s) traité(s)&quot;,
                metadata={
                    'extracted_dir': extracted_dir,
                    'dq_out_dir': dq_out_dir,
                    'total_files': len(csv_files),
                    'successful_files': len(successful),
                    'results': results
                }
            )

        except Exception as e:
            error_msg = f&quot;Erreur critique lors du traitement DQ: {e}&quot;
            self.logger.error(error_msg, exc_info=True)
            return ProcessingResult(
                success=False,
                error=error_msg
            )

    def process_file(self, csv_file_path: str) -&gt; ProcessingResult:

        try:
            # Charger la configuration pour résoudre les répertoires
            settings = self.config_loader.config
            dq_config = settings.get('data_quality', {})

            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            self.logger.info(f&quot;Processing single file: {csv_file_path}&quot;)

            # Déléguer au traitement interne
            return self._process_single_csv_file(
                csv_file_path=csv_file_path,
                dq_out_dir=dq_out_dir,
                dq_reports_dir=dq_reports_dir
            )

        except Exception as e:
            error_msg = f&quot;Erreur lors du traitement du fichier {csv_file_path}: {e}&quot;
            self.logger.error(error_msg, exc_info=True)
            return ProcessingResult(
                success=False,
                error=error_msg,
                metadata={'csv_file': csv_file_path}
            )

    def cleanup_temp_files(self, temp_dir: Optional[str] = None, max_age_hours: int = 72) -&gt; ProcessingResult:

        # Si un répertoire spécifique est fourni, nettoyer uniquement celui-ci
        if temp_dir:
            try:
                deleted_files = []
                if Path(temp_dir).exists():
                    deleted_files = self._cleanup_directory(temp_dir, max_age_hours)

                message = f&quot;Nettoyage DQ temp terminé: {len(deleted_files)} fichier(s) supprimé(s)&quot;
                self.logger.info(message)

                return ProcessingResult(
                    success=True,
                    message=message,
                    metadata={
                        'temp_dir': temp_dir,
                        'max_age_hours': max_age_hours,
                        'deleted_files': deleted_files
                    }
                )

            except Exception as e:
                error_msg = f&quot;Erreur lors du nettoyage de {temp_dir}: {e}&quot;
                self.logger.error(error_msg)
                return ProcessingResult(
                    success=False,
                    error=error_msg,
                    metadata={'temp_dir': temp_dir}
                )

        # Sinon, déléguer au nettoyage complet des répertoires DQ standard
        return self.cleanup_old_dq_files(max_age_hours=max_age_hours)

    def _process_single_csv_file(self,
                                csv_file_path: str,
                                dq_out_dir: str,
                                dq_reports_dir: str) -&gt; ProcessingResult:

        # Lazy imports — voir module docstring. Garde dq_processor.py importable
        # même si la lib `dataquality` n'est pas installée.
        from modules.dq import (
            DataObjectFactory,
            DQRunner,
            DataObjectError,
            DataObjectResolvingError,
        )

        csv_file = Path(csv_file_path)

        try:
            self.logger.info(f&quot;Processing CSV file: {csv_file.name}&quot;)

            # 1.a. Répertoires de sortie
            Path(dq_out_dir).mkdir(parents=True, exist_ok=True)
            Path(dq_reports_dir).mkdir(parents=True, exist_ok=True)

            table_name = self._extract_table_name(csv_file.name)
            step_key = f&quot;DQ:{table_name}&quot;
            input_filename = csv_file.name

            # 1.b. Idempotence — short-circuit si déjà traité avec le même fichier
            if self.tracker.is_step_completed(table_name, step_key):
                existing_info = self.tracker.get_step_info(table_name, step_key)
                if existing_info and existing_info.get('input_filename') == input_filename:
                    output_path = existing_info.get('output_path')
                    if output_path and Path(output_path).exists():
                        self.logger.info(
                            f&quot;Table {table_name} already processed from {input_filename}, skipping&quot;
                        )
                        return ProcessingResult(
                            success=True,
                            message=f&quot;Already processed: {table_name}&quot;,
                            metadata={
                                'csv_file': csv_file_path,
                                'output_path': output_path,
                                'already_processed': True,
                            }
                        )

            # 1.c. Empty file — comportement préservé : succès sans validation
            if not csv_file.exists():
                error_msg = f&quot;CSV file not found: {csv_file_path}&quot;
                self.logger.error(error_msg)
                return ProcessingResult(
                    success=False, error=error_msg, metadata={'csv_file': csv_file_path}
                )
            if csv_file.stat().st_size == 0:
                self.logger.warning(f&quot;Empty CSV file: {csv_file.name}, skipping&quot;)
                return ProcessingResult(
                    success=True,
                    message=f&quot;Empty CSV file skipped: {csv_file.name}&quot;,
                    rows_processed=0,
                    metadata={'csv_file': csv_file_path, 'empty_file': True},
                )

            # 2. Résoudre le data contract YAML
            data_contract = self._identify_data_contract(csv_file.name)
            if data_contract is None:
                error_msg = (
                    f&quot;No YAML data contract found for {csv_file.name} in config/tables/&quot;
                )
                self.logger.error(error_msg)
                self._write_legacy_report(
                    csv_file.stem,
                    dq_reports_dir,
                    self._build_legacy_report_dict_from_exception(
                        csv_file.name, FileNotFoundError(error_msg)
                    ),
                )
                return ProcessingResult(
                    success=False, error=error_msg, metadata={'csv_file': csv_file_path}
                )

            # 3. Construire le DataObject via la factory
            try:
                data_obj = DataObjectFactory.create(dc=data_contract, path=csv_file)
            except (DataObjectResolvingError, DataObjectError) as e:
                error_msg = f&quot;DataObjectFactory failed for {csv_file.name}: {e}&quot;
                self.logger.error(error_msg)
                self._write_legacy_report(
                    csv_file.stem,
                    dq_reports_dir,
                    self._build_legacy_report_dict_from_exception(csv_file.name, e),
                )
                return ProcessingResult(
                    success=False, error=str(e), metadata={'csv_file': csv_file_path}
                )

            # 4. Lancer les checks DQ — DQRunner instancié localement (lazy)
            try:
                self.logger.debug(f&quot;Running DQRunner on {csv_file.name}&quot;)
                runner = DQRunner()
                result: DQRunnerResult = runner.run(data_obj)
            except Exception as e:  # noqa: BLE001 — runner crash should not kill pipeline
                error_msg = f&quot;DQRunner crashed on {csv_file.name}: {e}&quot;
                self.logger.exception(error_msg)
                self._write_legacy_report(
                    csv_file.stem,
                    dq_reports_dir,
                    self._build_legacy_report_dict_from_exception(csv_file.name, e),
                )
                return ProcessingResult(
                    success=False, error=str(e), metadata={'csv_file': csv_file_path}
                )

            is_valid = bool(getattr(result, 'is_valid', False))

            # 5. Matérialiser le parquet dans dq_out_dir avec le nom du CSV
            parquet_filename = f&quot;{csv_file.stem}.parquet&quot;
            parquet_path = Path(dq_out_dir) / parquet_filename
            self._materialize_parquet(result, parquet_path, data_contract)

            # 6. Écrire le rapport JSON au format legacy
            report_dict = self._build_legacy_report_dict(
                csv_file.name, result, success=is_valid
            )
            self._write_legacy_report(csv_file.stem, dq_reports_dir, report_dict)

            # 7. Idempotence — marquer comme complété uniquement si validation OK
            if is_valid:
                self.tracker.mark_step_completed(table_name, step_key, {
                    'status': 'SUCCESS',
                    'input_filename': input_filename,
                    'output_path': str(parquet_path),
                })

            total_rows = int(getattr(result, 'total_row_count', 0) or 0)
            invalid_rows = int(getattr(result, 'total_error_row_count', 0) or 0)
            valid_rows = max(total_rows - invalid_rows, 0)

            return ProcessingResult(
                success=is_valid,
                message=(
                    f&quot;DQ processing completed for {csv_file.name}&quot;
                    if is_valid
                    else f&quot;DQ validation failed for {csv_file.name}&quot;
                ),
                rows_processed=total_rows,
                error=None if is_valid else f&quot;DQ validation failed for {csv_file.name}&quot;,
                metadata={
                    'csv_file': csv_file_path,
                    'parquet_file': str(parquet_path),
                    'valid_rows': valid_rows,
                    'invalid_rows': invalid_rows,
                    'dq_report_path': str(
                        Path(dq_reports_dir) / f&quot;{csv_file.stem}_dq_report.json&quot;
                    ),
                }
            )

        except Exception as e:
            error_msg = f&quot;Erreur lors du traitement DQ de {csv_file_path}: {e}&quot;
            self.logger.error(error_msg, exc_info=True)
            return ProcessingResult(
                success=False,
                error=error_msg,
                metadata={'csv_file': csv_file_path}
            )

    def _discover_csv_files(self, extracted_dir: str) -&gt; List[str]:
        &quot;&quot;&quot;Découvre tous les fichiers CSV dans le répertoire extrait.&quot;&quot;&quot;
        csv_files = []
        extracted_path = Path(extracted_dir)

        if not extracted_path.exists():
            self.logger.warning(f&quot;Extracted directory does not exist: {extracted_dir}&quot;)
            return []

        # Rechercher tous les fichiers CSV récursivement
        for csv_file in extracted_path.rglob(&quot;*.csv&quot;):
            csv_files.append(str(csv_file))

        csv_files.sort()  # Tri alphabétique pour un traitement déterministe
        self.logger.info(f&quot;Found {len(csv_files)} CSV files in {extracted_dir}&quot;)

        return csv_files

    @staticmethod
    def _extract_table_name(filename: str) -&gt; str:
        &quot;&quot;&quot;Extrait le nom de table en supprimant le timestamp du nom de fichier.

        Supporte: TABLE-YYYYMMDDHHmmss, TABLE_YYYYMMDD_HHMMSS, TABLE_YYYYMMDDHHmmss
        &quot;&quot;&quot;
        stem = Path(filename).stem

        # 1. Tiret + timestamp: NOM-YYYYMMDDTHHmmss ou NOM-YYYYMMDDHHmmss
        clean = re.sub(r'-\d{8}T?\d{6}$', '', stem)

        # 2. Underscore timestamps en boucle
        changed = True
        while changed:
            changed = False
            parts = clean.split('_')
            if len(parts) &gt;= 3:
                if (parts[-2].isdigit() and len(parts[-2]) == 8
                        and parts[-1].isdigit() and len(parts[-1]) == 6):
                    clean = '_'.join(parts[:-2])
                    changed = True
                    continue
            if len(parts) &gt;= 2:
                if parts[-1].isdigit() and len(parts[-1]) &gt;= 8:
                    clean = '_'.join(parts[:-1])
                    changed = True
                    continue

        return clean.upper()

    def _identify_data_contract(self, filename: str) -&gt; Optional[DataContract]:

        # Lazy import — le module reste importable si la lib dataquality manque
        from modules.dq import (
            DataContractError,
            DataContractLoadError,
            DataContractNotFoundError,
        )

        try:
            base_name = self._extract_table_name(filename)
            candidates = [
                base_name,
                f&quot;T_{base_name}&quot;,
                base_name.replace('_', ''),
            ]

            tables_dir = Path(self.config_loader.config_path).parent / &quot;tables&quot;
            if not tables_dir.exists():
                self.logger.warning(f&quot;Tables config dir does not exist: {tables_dir}&quot;)
                return None

            for table_name in candidates:
                for ext in (&quot;.yaml&quot;, &quot;.yml&quot;):
                    yaml_path = tables_dir / f&quot;{table_name.lower()}{ext}&quot;
                    if yaml_path.exists():
                        try:
                            contract = self._load_data_contract(yaml_path)
                            self.logger.debug(
                                f&quot;Loaded data contract for {filename}: {yaml_path.name}&quot;
                            )
                            return contract
                        except (DataContractLoadError, DataContractNotFoundError, DataContractError) as e:
                            self.logger.warning(
                                f&quot;YAML found but contract load failed for {yaml_path}: {e}&quot;
                            )
                            return None

            return None

        except Exception as e:  # noqa: BLE001 — defensive: never let resolution crash the processor
            self.logger.debug(f&quot;Could not identify data contract for {filename}: {e}&quot;)
            return None

    @staticmethod
    def _load_data_contract(yaml_path: Path) -&gt; DataContract:

        from modules.dq import DataContract  # noqa: PLC0415 — lazy by design
        return DataContract(str(yaml_path))

    # ----------------------------------------------------------------------
    # Helpers d'isolation autour de la nouvelle API DQ
    # ----------------------------------------------------------------------

    def _materialize_parquet(
        self,
        result: DQRunnerResult,
        target: Path,
        contract: DataContract,
    ) -&gt; None:

        target.parent.mkdir(parents=True, exist_ok=True)

        handle = getattr(result, 'parquet_handle', None)
        if handle is not None:
            src_path_attr = (
                getattr(handle, 'path', None)
                or getattr(handle, 'parquet_path', None)
            )
            if src_path_attr is not None:
                src_path = Path(src_path_attr)
                if src_path.exists():
                    if src_path.resolve() != target.resolve():
                        shutil.copy2(src_path, target)
                    self.logger.info(f&quot;Parquet materialized: {target}&quot;)
                    return

        # Fallback : aucun parquet produit → on écrit un parquet vide pour la traçabilité
        try:
            columns = list(getattr(contract, 'get_columns', []) or [])
        except Exception:  # noqa: BLE001 — best effort
            columns = []
        empty_df = pd.DataFrame(columns=columns)
        empty_df.to_parquet(target, index=False)
        self.logger.warning(f&quot;Empty parquet written (no parquet_handle): {target}&quot;)

    def _build_legacy_report_dict(
        self,
        filename: str,
        result: DQRunnerResult,
        success: bool,
    ) -&gt; Dict[str, Any]:

        is_valid = bool(getattr(result, 'is_valid', False))
        total_rows = int(getattr(result, 'total_row_count', 0) or 0)
        invalid_rows = int(getattr(result, 'total_error_row_count', 0) or 0)
        valid_rows = max(total_rows - invalid_rows, 0)

        errors: List[Dict[str, Any]] = []
        for check in getattr(result, 'checks', []) or []:
            status = getattr(check, 'status', None)
            status_str = str(status) if status is not None else ''
            if status_str.endswith('NOK') or status_str.endswith('ERR'):
                errors.append({
                    'code': getattr(check, 'dq_code', None),
                    'info': getattr(check, 'error_info', None),
                    'details': getattr(check, 'error_details', None),
                })

        return {
            'filename': filename,
            'timestamp': datetime.now().isoformat(),
            'success': success,
            'is_valid': is_valid,
            'total_rows': total_rows,
            'valid_rows': valid_rows,
            'invalid_rows': invalid_rows,
            'errors': errors,
            'warnings': [],
        }

    def _build_legacy_report_dict_from_exception(
        self,
        filename: str,
        exc: Exception,
    ) -&gt; Dict[str, Any]:
        &quot;&quot;&quot;Variante du rapport pour les crashs runtime ou erreurs de résolution.&quot;&quot;&quot;
        return {
            'filename': filename,
            'timestamp': datetime.now().isoformat(),
            'success': False,
            'is_valid': False,
            'total_rows': 0,
            'valid_rows': 0,
            'invalid_rows': 0,
            'errors': [{
                'code': type(exc).__name__,
                'info': str(exc),
                'details': None,
            }],
            'warnings': [],
        }

    def _write_legacy_report(
        self,
        csv_stem: str,
        reports_dir: str,
        report_dict: Dict[str, Any],
    ) -&gt; None:

        try:
            Path(reports_dir).mkdir(parents=True, exist_ok=True)
            report_path = Path(reports_dir) / f&quot;{csv_stem}_dq_report.json&quot;
            with open(report_path, 'w', encoding='utf-8') as f:
                json.dump(report_dict, f, indent=2, ensure_ascii=False, default=str)
            self.logger.debug(f&quot;DQ report saved: {report_path}&quot;)
        except Exception as e:  # noqa: BLE001 — never let report write kill the processor
            self.logger.error(f&quot;Error saving DQ report for {csv_stem}: {e}&quot;)

    def cleanup_old_dq_files(self,
                           max_age_hours: int = 72) -&gt; ProcessingResult:

        try:
            settings = self.config_loader.config
            dq_config = settings.get('data_quality', {})

            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            deleted_files = []

            # Nettoyer les répertoires
            for directory in [dq_out_dir, dq_reports_dir]:
                if Path(directory).exists():
                    deleted_count = self._cleanup_directory(directory, max_age_hours)
                    deleted_files.extend(deleted_count)

            message = f&quot;Nettoyage DQ terminé: {len(deleted_files)} fichier(s) supprimé(s)&quot;
            self.logger.info(message)

            return ProcessingResult(
                success=True,
                message=message,
                metadata={
                    'dq_out_dir': dq_out_dir,
                    'dq_reports_dir': dq_reports_dir,
                    'max_age_hours': max_age_hours,
                    'deleted_files': deleted_files
                }
            )

        except Exception as e:
            error_msg = f&quot;Erreur lors du nettoyage DQ: {e}&quot;
            self.logger.error(error_msg)
            return ProcessingResult(
                success=False,
                error=error_msg
            )

    def _cleanup_directory(self, directory: str, max_age_hours: int) -&gt; List[str]:
        &quot;&quot;&quot;Nettoie les anciens fichiers d'un répertoire.&quot;&quot;&quot;
        deleted_files = []
        cutoff_time = datetime.now().timestamp() - (max_age_hours * 3600)

        try:
            for file_path in Path(directory).rglob(&quot;*&quot;):
                if file_path.is_file() and file_path.stat().st_mtime &lt; cutoff_time:
                    try:
                        file_path.unlink()
                        deleted_files.append(file_path.name)
                        self.logger.debug(f&quot;Fichier DQ supprimé: {file_path.name}&quot;)
                    except Exception as e:
                        self.logger.error(f&quot;Erreur suppression {file_path.name}: {e}&quot;)

        except Exception as e:
            self.logger.error(f&quot;Erreur lors du nettoyage de {directory}: {e}&quot;)

        return deleted_files

    def get_dq_statistics(self) -&gt; Dict[str, Any]:
        &quot;&quot;&quot;Récupère les statistiques des traitements DQ.&quot;&quot;&quot;
        try:
            settings = self.config_loader.config
            dq_config = settings.get('data_quality', {})

            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            stats = {
                'dq_out_dir': dq_out_dir,
                'dq_reports_dir': dq_reports_dir,
                'parquet_files': 0,
                'total_parquet_size_mb': 0.0,
                'reports_count': 0,
                'latest_processing': None
            }

            # Compter les fichiers parquet
            if Path(dq_out_dir).exists():
                parquet_files = list(Path(dq_out_dir).glob(&quot;*.parquet&quot;))
                stats['parquet_files'] = len(parquet_files)

                total_size = sum(f.stat().st_size for f in parquet_files)
                stats['total_parquet_size_mb'] = round(total_size / (1024 * 1024), 2)

                if parquet_files:
                    latest_file = max(parquet_files, key=lambda f: f.stat().st_mtime)
                    stats['latest_processing'] = datetime.fromtimestamp(latest_file.stat().st_mtime).isoformat()

            # Compter les rapports
            if Path(dq_reports_dir).exists():
                report_files = list(Path(dq_reports_dir).glob(&quot;*.json&quot;))
                stats['reports_count'] = len(report_files)

            return stats

        except Exception as e:
            self.logger.error(f&quot;Erreur lors du calcul des statistiques DQ: {e}&quot;)
            return {'error': str(e)}
